const revision = $json;

if (!revision.article_id || !revision.current_package_json || !revision.revision_instruction) {
  throw new Error('No unprocessed doctor revision request is available.');
}

let currentPackage;
try {
  currentPackage = typeof revision.current_package_json === 'string'
    ? JSON.parse(revision.current_package_json)
    : revision.current_package_json;
} catch (error) {
  throw new Error('The current article package is not valid JSON: ' + error.message);
}

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['article_html', 'review_document_markdown', 'metadata'],
  properties: {
    article_html: { type: 'string' },
    review_document_markdown: { type: 'string' },
    metadata: {
      type: 'object',
      additionalProperties: false,
      required: ['h1', 'seo_title', 'slug', 'meta_description', 'primary_search_intent', 'word_count'],
      properties: {
        h1: { type: 'string' },
        seo_title: { type: 'string' },
        slug: { type: 'string' },
        meta_description: { type: 'string' },
        primary_search_intent: { type: 'string' },
        word_count: { type: 'integer' }
      }
    }
  }
};

const practiceContext = {
  doctor_name: revision.doctor_name,
  doctor_credentials: revision.credentials,
  practice_name: revision.practice_name,
  website_domain: revision.website_domain,
  publisher_config_reference: revision.publisher_config_reference,
  campaign_name: revision.campaign_name,
  campaign_month: revision.campaign_month,
  topic_title: revision.topic_title,
  topic_description: revision.topic_description,
  interview_guidance: revision.interview_guidance
};

const input = [
  'DOCTOR REVISION REQUEST',
  revision.revision_instruction,
  '',
  'CURRENT ARTICLE VERSION',
  String(revision.current_version),
  '',
  'CURRENT PUBLICATION PACKAGE',
  JSON.stringify(currentPackage, null, 2),
  '',
  'ORIGINAL INTERVIEW TRANSCRIPT',
  revision.transcript || '',
  '',
  'PRIOR REVISION HISTORY',
  revision.revision_history_json || '[]',
  '',
  'PRACTICE CONTEXT',
  JSON.stringify(practiceContext, null, 2)
].join('\n');

return [{
  json: {
    ...revision,
    next_version: Number(revision.current_version) + 1,
    openai_body: {
      model: 'gpt-6-astra',
      tools: [{ type: 'web_search' }],
      include: ['web_search_call.action.sources'],
      instructions: "# Article Revision Master Prompt\n\nYou are the revision editor for an expert-authored healthcare article.\n\nYour task is to revise the current publication package in response to the doctor's written request. Modify the existing article; do not replace it with an unrelated article or restart from a blank page.\n\n## Source priority\n\nUse the sources in this order:\n\n1. The doctor's current revision request.\n2. The original interview transcript.\n3. The current article and its review document.\n4. Prior revision history.\n5. Current authoritative research when a requested change requires factual verification.\n\nThe transcript remains the source of the doctor's experience, professional judgment, examples, and voice. Never invent patient stories, clinical experience, credentials, treatment practices, or personal opinions.\n\n## Revision rules\n\n- Address every reasonable item in the doctor's request.\n- Preserve unaffected material whenever it remains accurate and useful.\n- Keep the article in the doctor's natural first-person voice.\n- Preserve the central narrative unless the doctor explicitly asks to change it.\n- Do not silently make unrelated editorial changes.\n- Do not introduce new clinical claims without checking authoritative sources.\n- If a requested statement would be inaccurate, unsafe, or unsupported, make the closest defensible revision and explain the limitation in the review document.\n- Keep all dynamic tokens exactly intact, including `{{DOCTOR_NAME}}`, `{{DOCTOR_CREDENTIALS}}`, `{{PRACTICE_NAME}}`, and `{{APPOINTMENT_URL}}`.\n- Preserve clean production HTML with no `<html>`, `<head>`, `<body>`, `<script>`, or `<style>` tags.\n- Preserve the five required metadata comments before the `<h1>`.\n- The production article must contain no internal review comments.\n\n## Required output\n\nReturn a complete two-artifact publication package:\n\n1. `article_html`: the full revised production HTML, not a diff.\n2. `review_document_markdown`: the full revised human-readable review document, not a change summary.\n3. `metadata`: the canonical H1, SEO title, slug, meta description, primary search intent, and word count.\n\nThe article shown in the review document must match `article_html` exactly in wording. Update the review document's sourcing, editorial notes, and expert-review checklist when the revision changes them.\n\nBefore returning the package, verify that the doctor's request has been addressed, the article remains grounded in the transcript, and the two artifacts are internally consistent.\n",
      input,
      text: {
        format: {
          type: 'json_schema',
          name: 'revised_article_publication_package',
          strict: true,
          schema
        }
      },
      max_output_tokens: 30000
    }
  }
}];

const response = $json;
const context = $('Prepare Revision Request').first().json;

if (response.error) {
  throw new Error('OpenAI article revision failed: ' + JSON.stringify(response.error));
}
if (response.status && response.status !== 'completed') {
  throw new Error('OpenAI revision response did not complete. Status: ' + response.status);
}

const message = (response.output || []).find((item) => item.type === 'message');
const outputText = message?.content?.find((item) => item.type === 'output_text')?.text;
if (!outputText) {
  throw new Error('OpenAI revision response did not contain structured output text.');
}

let publicationPackage;
try {
  publicationPackage = JSON.parse(outputText);
} catch (error) {
  throw new Error('Revised article package was not valid JSON: ' + error.message);
}

const html = publicationPackage.article_html || '';
const review = publicationPackage.review_document_markdown || '';
if (!html.trim() || !html.startsWith('<!-- SEO_TITLE:') || !html.includes('<h1>')) {
  throw new Error('Revised production HTML is empty or missing required metadata and H1.');
}
if (/<(?:html|head|body|script|style)(?:\s|>)/i.test(html)) {
  throw new Error('Revised production HTML contains a forbidden wrapper or executable/style tag.');
}
if (/<!--\s*(?:FACT CHECK|INTERVIEW BASIS|REVIEW NOTE|SOURCE|CLINICAL REVIEW|RESEARCH ADDITION)/i.test(html)) {
  throw new Error('Revised production HTML contains internal review comments.');
}
if (review.length < 1000) {
  throw new Error('Revised review document is unexpectedly short.');
}

const packageForStorage = {
  article_html: html,
  review_document_markdown: review,
  metadata: publicationPackage.metadata,
  openai_response_id: response.id,
  generated_at: new Date().toISOString(),
  revised_from_version: Number(context.current_version),
  revision_instruction: context.revision_instruction
};

return [{
  json: {
    article_id: context.article_id,
    interview_id: context.interview_id,
    campaign_id: context.campaign_id,
    doctor_id: context.doctor_id,
    practice_id: context.practice_id,
    approval_id: context.approval_id,
    current_version: Number(context.current_version),
    next_version: Number(context.next_version),
    doctor_review_days: Number(context.doctor_review_days || 5),
    revision_instruction: context.revision_instruction,
    package_json: JSON.stringify(packageForStorage),
    openai_response_id: response.id
  }
}];

