-- AAC Phase 1G
-- Preserve the prior version and promote a new canonical AI doctor revision.
ASSERT (
  SELECT COUNT(*)
  FROM `apex-marketing-n8n.automated_article_creation.articles`
  WHERE article_id = @article_id
    AND status = 'CHANGES_REQUESTED'
    AND current_version = CAST(@current_version AS INT64)
) = 1 AS 'The article is no longer awaiting this revision or its version changed.';

MERGE `apex-marketing-n8n.automated_article_creation.article_versions` T
USING (
  SELECT
    @article_id AS article_id,
    CAST(@next_version AS INT64) AS version_number,
    'AI_DOCTOR_REVISION' AS version_type,
    @package_json AS content,
    @revision_instruction AS revision_instruction,
    CURRENT_TIMESTAMP() AS created_at,
    'n8n:article-revision' AS created_by
) S
ON T.article_id = S.article_id AND T.version_number = S.version_number
WHEN NOT MATCHED THEN INSERT
  (article_id, version_number, version_type, content, revision_instruction, created_at, created_by)
VALUES
  (S.article_id, S.version_number, S.version_type, S.content, S.revision_instruction, S.created_at, S.created_by);

UPDATE `apex-marketing-n8n.automated_article_creation.articles`
SET
  status = 'DOCTOR_REVIEW_PENDING',
  current_version = CAST(@next_version AS INT64),
  doctor_review_deadline = TIMESTAMP_ADD(CURRENT_TIMESTAMP(), INTERVAL CAST(@doctor_review_days AS INT64) DAY),
  doctor_approved_at = NULL
WHERE article_id = @article_id;

UPDATE `apex-marketing-n8n.automated_article_creation.campaign_doctors`
SET status = 'DOCTOR_REVIEW_PENDING', updated_at = CURRENT_TIMESTAMP()
WHERE campaign_id = @campaign_id AND doctor_id = @doctor_id;

INSERT INTO `apex-marketing-n8n.automated_article_creation.workflow_events`
(event_id, entity_type, entity_id, event_type, event_timestamp, source_system, workflow_execution_id, payload)
VALUES (
  GENERATE_UUID(), 'article', @article_id, 'article.revised', CURRENT_TIMESTAMP(), 'n8n+openai', NULL,
  TO_JSON(STRUCT(
    CAST(@current_version AS INT64) AS previous_version,
    CAST(@next_version AS INT64) AS version_number,
    'AI_DOCTOR_REVISION' AS version_type,
    @approval_id AS approval_id,
    @openai_response_id AS openai_response_id
  ))
);

SELECT
  @article_id AS article_id,
  @doctor_id AS doctor_id,
  @campaign_id AS campaign_id,
  CAST(@next_version AS INT64) AS current_version,
  CAST(@doctor_review_days AS INT64) AS doctor_review_days,
  'DOCTOR_REVIEW_PENDING' AS status;
